package com.utegear.service;
import com.utegear.dto.catalog.BrandSummary; import com.utegear.entity.Brand; import com.utegear.exception.ApiException; import com.utegear.repository.BrandRepository; import com.utegear.util.Slugifier; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class BrandService { private final BrandRepository repository; public BrandService(BrandRepository repository){this.repository=repository;} @Transactional public BrandSummary create(String name,String description){String slug=Slugifier.slugify(name); if(repository.existsByNameIgnoreCase(name.trim())||repository.existsBySlug(slug)) throw new ApiException(HttpStatus.CONFLICT,"BRAND_ALREADY_EXISTS","Thương hiệu đã tồn tại"); return BrandSummary.from(repository.save(new Brand(name.trim(),slug,description)));} @Transactional(readOnly=true) public List<BrandSummary> active(){return repository.findByActiveTrueOrderByNameAsc().stream().map(BrandSummary::from).toList();} }
